/*
 * Accent presets, switched at runtime with data-accent on <html> (no attribute = blue).
 * The attribute also works on any element to give one section its own accent.
 * Generated by tooling/scripts/gen-theme.py from the theme-<name> registry items; import after the theme.
 */

html[data-accent="blue"],
[data-accent="blue"] {
  --primary: oklch(52% 0.145 250);
  --primary-hover: oklch(48.5% 0.138 250);
  --primary-active: oklch(45% 0.1283 250);
  --primary-foreground: oklch(100% 0 0);
  --primary-subtle: oklch(52% 0.145 250 / 0.1);
  --primary-subtle-hover: oklch(52% 0.145 250 / 0.16);
  --primary-border: oklch(52% 0.145 250 / 0.32);
  --primary-text: oklch(50.5% 0.1305 250);
  --ring: oklch(52% 0.145 250);
  --selection: oklch(52% 0.145 250 / 0.22);
}

html[data-accent="blue"].dark,
.dark [data-accent="blue"] {
  --primary: oklch(72% 0.125 245);
  --primary-hover: oklch(75.5% 0.125 245);
  --primary-active: oklch(79% 0.1142 245);
  --primary-foreground: oklch(20% 0.02 245);
